    public override Dictionary<string, object> parseTrade(object trade, object market = null)
    {
        //
        // fetchTrades
        //     {
        //         "id": "875fba11-f8a1-42ad-915d-012ccb375e8a",
        //         "price": "2114.77",
        //         "qty": "0.01000",
        //         "quoteQty": "21.1477000",
        //         "time": 1775594995485,
        //         "isBuyerMaker": false,
        //         "isBestMatch": true
        //     }
        //
        // fetchMyTrades (spot)
        //     {
        //         "symbol": "DOGEUSDT",
        //         "id": 736825748291060702,
        //         "orderId": 736825748215563230,
        //         "price": "0.09349",
        //         "qty": "250.0",
        //         "quoteQty": "23.3725",
        //         "commission": "0.0233725",
        //         "time": 1775672947953,
        //         "isBuyer": false
        //     }
        //
        // fetchMyTrades (contract)
        //     {
        //         "id": 737074389731770728,
        //         "orderId": 737074043320009064,
        //         "symbol": "DOGEUSDT",
        //         "buyer": true,
        //         "commission": "0.00183500",
        //         "commissionAsset": "USDT",
        //         "maker": true,
        //         "price": "0.09175",
        //         "qty": "100",
        //         "quoteQty": "9.17500",
        //         "realizedPnl": "0",
        //         "side": "BUY",
        //         "positionSide": "LONG",
        //         "time": 1775732228692
        //     }
        //
        Int64? timestamp = this.safeInteger(trade, "time");
        bool? isBuyer = this.safeBool(trade, "isBuyer");
        string? side = this.safeStringLower(trade, "side");
        bool? isBuyerMaker = this.safeBool(trade, "isBuyerMaker");
        if ((isBuyer != null))
        {
            side = isBuyer == true ? "buy" : "sell";
        } else if ((isBuyerMaker != null))
        {
            side = isBuyerMaker == true ? "sell" : "buy";
        }
        string? tradeMarketId = this.safeString(trade, "symbol");
        string? realizedPnl = this.safeString(trade, "realizedPnl");
        string tradeMarketType = "spot";
        if ((realizedPnl != null))
        {
            tradeMarketType = "swap";
        }
        object marketResolved = ((market == null)) ? this.safeMarket(tradeMarketId, null, null, tradeMarketType) : market;
        object isSpot = null;
        if ((market == null))
        {
            isSpot = tradeMarketType == "spot";
        } else
        {
            isSpot = getValue(market, "spot");
        }
        Dictionary<string, object> fee = null;
        string? commission = this.safeString(trade, "commission");
        if ((commission != null))
        {
            string? commissionAsset = this.safeString(trade, "commissionAsset");
            string? feeCurrency = this.safeCurrencyCode(commissionAsset);
            if (isEqual(isSpot, true))
            {
                if (side == "buy")
                {
                    feeCurrency = this.safeString(marketResolved, "base");
                } else
                {
                    feeCurrency = this.safeString(marketResolved, "quote");
                }
            }
            fee = new Dictionary<string, object>() {
                { "cost", commission },
                { "currency", feeCurrency },
            };
        }
        bool? isMaker = this.safeBool(trade, "maker");
        string? takerOrMaker = null;
        if ((isMaker != null))
        {
            takerOrMaker = isMaker == true ? "maker" : "taker";
        } else if ((isBuyerMaker != null))
        {
            takerOrMaker = "taker";
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", this.safeString(trade, "id") },
            { "order", this.safeString(trade, "orderId") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", getValue(marketResolved, "symbol") },
            { "type", null },
            { "takerOrMaker", takerOrMaker },
            { "side", side },
            { "price", this.safeString(trade, "price") },
            { "amount", this.safeString(trade, "qty") },
            { "cost", this.safeString(trade, "quoteQty") },
            { "fee", fee },
        }, marketResolved);
    }

