    /**
     * @method
     * @description fetch open positions for a single market
     * @name weex#fetchPositionsForSymbol
     * @see https://www.weex.com/api-doc/contract/Account_API/GetSinglePosition
     * @description fetch all open positions for specific symbol
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/?id=position-structure}
     */
    public async override Task<List<ccxt.Position>> FetchPositionsForSymbol(string symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        bool? sandboxMode = this.safeBool(this.options, "sandboxMode", false);
        if ((sandboxMode == true))
        {
            // the demo trading API does not provide a single-position endpoint
            return await this.FetchPositions(new List<object>() {(market.ContainsKey("symbol") ? market["symbol"] : null)}, parameters);
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "symbol", (market.ContainsKey("id") ? market["id"] : null) },
        };
        List<object> response = await this.contractPrivateGetCapiV3AccountPositionSinglePosition(this.extend(request, parameters));
        return ccxt.BaseExchange.ToPositionList(this.parsePositions(response, new List<object>() {(market.ContainsKey("symbol") ? market["symbol"] : null)}));
    }

    public override Dictionary<string, object> parsePosition(object position, IDictionary<string, object> market = null)
    {
        //
        //     {
        //         "id": 737191855967437160,
        //         "asset": "USDT",
        //         "symbol": "DOGEUSDT",
        //         "side": "LONG",
        //         "marginType": "CROSSED",
        //         "separatedMode": "COMBINED",
        //         "separatedOpenOrderId": 0,
        //         "leverage": "20.00",
        //         "size": "300",
        //         "openValue": "27.96900",
        //         "openFee": "0.02237520",
        //         "fundingFee": "0",
        //         "marginSize": "100",
        //         "isolatedMargin": "0",
        //         "isAutoAppendIsolatedMargin": false,
        //         "cumOpenSize": "300",
        //         "cumOpenValue": "27.96900",
        //         "cumOpenFee": "0.02237520",
        //         "cumCloseSize": "0",
        //         "cumCloseValue": "0",
        //         "cumCloseFee": "0",
        //         "cumFundingFee": "0",
        //         "cumLiquidateFee": "0",
        //         "createdMatchSequenceId": 5762536243,
        //         "updatedMatchSequenceId": 5762741613,
        //         "createdTime": 1775760234825,
        //         "updatedTime": 1775763170789,
        //         "unrealizePnl": "0.00600",
        //         "liquidatePrice": "0"
        //     }
        //
        // watchPoisions
        //     {
        //         "id": "739004481374519656",
        //         "coin": "USDT",
        //         "symbol": "DOGEUSDT",
        //         "side": "LONG",
        //         "marginMode": "CROSSED",
        //         "separatedMode": "COMBINED",
        //         "separatedOpenOrderId": "0",
        //         "leverage": "11",
        //         "size": "100",
        //         "openValue": "9.31100",
        //         "openFee": "0.00744880",
        //         "fundingFee": "0",
        //         "isolatedMargin": "0",
        //         "autoAppendIsolatedMargin": false,
        //         "cumOpenSize": "100",
        //         "cumOpenValue": "9.31100",
        //         "cumOpenFee": "0.00744880",
        //         "cumCloseSize": "0",
        //         "cumCloseValue": "0",
        //         "cumCloseFee": "0",
        //         "cumFundingFee": "0",
        //         "cumLiquidateFee": "0",
        //         "createdMatchSequenceId": "5792711540",
        //         "updatedMatchSequenceId": "5792711540",
        //         "createdTime": "1776192398399",
        //         "updatedTime": "1776192398399"
        //     }
        //
        string? errorMessage = this.safeString(position, "errorMsg");
        string? errorCode = this.safeString(position, "errorCode");
        if ((errorMessage != null))
        {
            this.handleOrderOrPositionError(errorCode, errorMessage, position);
        }
        string? marketId = this.fromSandboxMarketId(this.safeString2(position, "symbol", "coinId")); // coinId might be used in testnet: https://github.com/ccxt/ccxt/issues/28576#issuecomment-4439400273
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market, null, "contract");
        Int64? timestamp = this.safeInteger(position, "createdTime");
        string? marginType = this.safeString2(position, "marginType", "marginMode");
        string marginMode = "cross";
        if (marginType == "ISOLATED")
        {
            marginMode = "isolated";
        }
        string? separatedMode = this.safeString(position, "separatedMode");
        bool? hedged = null;
        if (separatedMode == "COMBINED")
        {
            hedged = false;
        } else if (separatedMode == "SEPARATED")
        {
            hedged = true;
        }
        string? notional = this.safeString(position, "openValue");
        string? size = this.safeString(position, "size");
        string? entryPrice = Precise.stringDiv(notional, size);
        return this.safePosition(new Dictionary<string, object>() {
            { "symbol", (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null) },
            { "id", this.safeString2(position, "id", "positionId") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "contracts", this.parseNumber(size) },
            { "contractSize", null },
            { "side", this.safeStringLower(position, "side") },
            { "notional", this.parseNumber(notional) },
            { "leverage", this.safeNumber(position, "leverage") },
            { "unrealizedPnl", this.safeNumber(position, "unrealizePnl") },
            { "realizedPnl", null },
            { "collateral", null },
            { "entryPrice", this.parseNumber(entryPrice) },
            { "markPrice", null },
            { "liquidationPrice", this.safeNumber(position, "liquidatePrice") },
            { "marginMode", marginMode },
            { "hedged", hedged },
            { "maintenanceMargin", null },
            { "maintenanceMarginPercentage", null },
            { "initialMargin", this.safeNumber(position, "marginSize") },
            { "initialMarginPercentage", null },
            { "marginRatio", null },
            { "lastUpdateTimestamp", this.safeInteger(position, "updatedTime") },
            { "lastPrice", null },
            { "stopLossPrice", null },
            { "takeProfitPrice", null },
            { "percentage", null },
            { "info", position },
        });
    }

